/**
 * Kumva SendMessage Node
 * Uses Africa's Talking config from Start Campaign node
 */

module.exports = function(RED) {
  const AfricasTalkingService = require('kumva-insights/utils/africastalking');
  const helpers = require('kumva-insights/utils/helpers');

  function KumvaSendMessageNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const retryTracker = {};

    function getPhoneNumber(msg) {
      const source = config.phoneSource || 'msg';
      switch(source) {
        case 'static':
          return config.staticPhone;
        case 'variable':
          return msg[config.variablePhone || 'phoneNumber'];
        case 'msg':
        default:
          return msg.phoneNumber;
      }
    }

    function getMessageContent(msg) {
      const messageType = config.messageType || 'sms';
      let content;
      switch(messageType) {
        case 'sms':
          content = config.messageContent || msg.initialMessage || '';
          break;
        case 'ivr-audio':
          content = config.audioUrl || '';
          break;
        case 'ivr-tts':
          content = config.ttsText || msg.initialMessage || '';
          break;
        default:
          content = '';
      }
      return helpers.resolveVariables(content, msg);
    }

    async function sendSMS(phoneNumber, message, msg, africasTalkingService) {
      try {
        const shortCode = msg.shortCode || config.shortCode || null;
        const result = await africasTalkingService.sendSMS(phoneNumber, message, shortCode);
        
        if (result.success) {
          node.log(`SMS sent to ${phoneNumber}`);
          return { success: true, messageId: result.messageId, fullResult: result.data };
        } else {
          throw new Error(result.error || 'Failed to send SMS');
        }
      } catch (error) {
        node.error(`SMS send error: ${error.message}`);
        return { success: false, error: error.message };
      }
    }

    async function sendIVR(phoneNumber, ivrConfig, msg, africasTalkingService) {
      try {
        const callerId = msg.callerId || config.callerId || null;
        const ivrOptions = { callerId, ...ivrConfig };
        const result = await africasTalkingService.sendIVR(phoneNumber, ivrOptions);
        
        if (result.success) {
          node.log(`IVR sent to ${phoneNumber}`);
          return { success: true, sessionId: result.sessionId, fullResult: result.data };
        } else {
          throw new Error(result.error || 'Failed to send IVR');
        }
      } catch (error) {
        node.error(`IVR send error: ${error.message}`);
        return { success: false, error: error.message };
      }
    }

    async function handleSendMessage(msg, sendFn) {
      const retryKey = msg.sessionId || `${msg.phoneNumber}_${Date.now()}`;
      const currentAttempt = (retryTracker[retryKey] || 0) + 1;
      retryTracker[retryKey] = currentAttempt;

      try {
        const result = await sendFn();
        if (result.success) {
          delete retryTracker[retryKey];
          return result;
        } else {
          const maxRetries = config.maxRetries || 3;
          if (config.retryOnFailure && currentAttempt < maxRetries) {
            node.warn(`Send failed, retrying (${currentAttempt}/${maxRetries})`);
            await helpers.delay(1000 * currentAttempt);
            return handleSendMessage(msg, sendFn);
          } else {
            throw new Error(result.error || 'Failed to send message');
          }
        }
      } catch (error) {
        delete retryTracker[retryKey];
        throw error;
      }
    }

    node.on('input', async function(msg) {
      try {
        const phoneNumber = getPhoneNumber(msg);
        if (!phoneNumber || !helpers.isValidPhoneNumber(phoneNumber)) {
          node.error(`Invalid phone number: ${phoneNumber}`);
          node.status({ fill: 'red', shape: 'ring', text: 'Invalid phone' });
          return;
        }

        // Get credentials from message (passed by Start Campaign)
        const credentials = msg.credentials;
        if (!credentials || !credentials.apiKey || !credentials.username) {
          node.error('No Africa\'s Talking credentials in message');
          node.status({ fill: 'red', shape: 'ring', text: 'No credentials' });
          return;
        }

        // Initialize service with credentials
        const africasTalkingService = new AfricasTalkingService({
          apiKey: credentials.apiKey,
          username: credentials.username
        });

        node.status({ fill: 'blue', shape: 'dot', text: 'Sending...' });

        const messageType = config.messageType || 'sms';
        let result;

        if (messageType === 'sms') {
          const content = getMessageContent(msg);
          if (!content) throw new Error('No message content');
          result = await handleSendMessage(msg, () => 
            sendSMS(phoneNumber, content, msg, africasTalkingService)
          );
        } else if (messageType === 'ivr-audio') {
          const audioUrl = getMessageContent(msg);
          if (!audioUrl) throw new Error('No audio URL');
          result = await handleSendMessage(msg, () =>
            sendIVR(phoneNumber, { audioUrl }, msg, africasTalkingService)
          );
        } else if (messageType === 'ivr-tts') {
          const ttsText = getMessageContent(msg);
          if (!ttsText) throw new Error('No TTS text');
          result = await handleSendMessage(msg, () =>
            sendIVR(phoneNumber, { ttsText }, msg, africasTalkingService)
          );
        }

        if (!result.success) throw new Error(result.error);

        const outputMsg = {
          ...msg,
          messageId: result.messageId || null,
          sessionId: result.sessionId || msg.sessionId,
          sendStatus: 'success',
          sendResult: result.fullResult,
          _kumva: {
            ...msg._kumva,
            lastMessageId: result.messageId,
            sentAt: new Date().toISOString()
          }
        };

        node.status({ fill: 'green', shape: 'dot', text: 'Sent' });
        node.send(outputMsg);

      } catch (error) {
        node.error(`SendMessage error: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error sending' });
        msg.sendStatus = 'failed';
        msg.sendError = error.message;
        node.send(msg);
      }
    });

    node.on('close', function(done) {
      Object.keys(retryTracker).forEach(key => delete retryTracker[key]);
      done();
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready' });
  }

  RED.nodes.registerType('kumva-send-message', KumvaSendMessageNode);
};